/* cppi::a0f23a332d173228d3bd6e6edbeafd20ce3225e9da855a1f4df4bb6a02642be0 */
select business_date as date_, security_id, 'EUGBR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-02' and business_date <= date '2025-06-02' and weight_ndo>0 and id_cppib_index = 'EUGBR_GR_USD_0_0'

/* cppi::61d1830d4ea73e5a4142f670ce89af712b685dee635f42568a3aa7992fc01471 */
select security_number_parent,holding_level,leg_no,id_cppibsec ,balance_nominal,abor_total_market_value_pc,abor_total_market_value_qc  from holdings.seed_holding_lookthrough 
where instrument_type_code_parent = 'CALL EPM' and business_date = date'2025-05-31'

